 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # ARC examples use a uniform background and a single-color outline.
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    bg = max(counts, key=counts.get)
    border = min((c for c in counts if c != bg), key=lambda c: counts[c])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == bg and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if not touches_edge:
                for y, x in cells:
                    out[y][x] = 4
    return out
